    :param exclude_methods: Exclude Methods
    :return:
    """
def get_user_attributes(cls: Any, exclude_methods: bool = True) -> list {
    base_attrs = dir(`type('dummy', (object, ), {}));
    this_cls_attrs = dir(cls);
    res = [];
    for attr in this_cls_attrs {
        if (
            base_attrs.count(attr) or (callable(getattr(cls, attr)) and exclude_methods)
